const listVisibleMachineSourcesForPrincipal = `-- name: ListVisibleMachineSourcesForPrincipal :many
WITH current_org_membership AS (
  SELECT om.role
  FROM org_memberships om
  WHERE om.org_id = $2
    AND (
      ($3::uuid IS NOT NULL AND om.user_id = $3::uuid)
      OR ($4::uuid IS NOT NULL AND om.org_api_key_id = $4::uuid)
    )
),
is_admin AS (
  SELECT EXISTS (
    SELECT 1
    FROM current_org_membership
    WHERE role IN ('owner', 'admin')
  ) AS value
),
visible_projects AS (
  SELECT DISTINCT roles.project_id
  FROM principal_project_authorization_roles roles
  WHERE roles.org_id = $2
    AND (
      ($3::uuid IS NOT NULL AND roles.user_id = $3::uuid)
      OR ($4::uuid IS NOT NULL AND roles.org_api_key_id = $4::uuid)
    )
    AND NOT (SELECT value FROM is_admin)
), visible_ids AS (
  SELECT m.id FROM machines m WHERE m.org_id = $2 AND m.deleted_at IS NULL AND (SELECT value FROM is_admin)
  UNION
  SELECT pmg.machine_id FROM project_machine_grants pmg JOIN visible_projects vp ON vp.project_id = pmg.project_id
   WHERE pmg.org_id = $2
), listed AS (
  SELECT m.id,
   CASE $5::text WHEN 'name' THEN lower(m.display_name) WHEN 'created_at' THEN to_char(m.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US') WHEN 'updated_at' THEN to_char(m.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US') WHEN 'provider' THEN m.provider WHEN 'source_kind' THEN m.source_kind WHEN 'lifecycle_state' THEN m.lifecycle_state WHEN 'connection_state' THEN c.connection_state END::text AS sort_key,
   false AS sort_is_null
  FROM visible_ids v JOIN machines m ON m.id = v.id
  JOIN machine_connection_states c ON c.org_id = m.org_id AND c.machine_id = m.id
  WHERE ($6::text = '' OR m.display_name ILIKE $6::text ESCAPE '\')
   AND (COALESCE(cardinality($7::text[]), 0) = 0 OR m.provider = ANY($7::text[]))
   AND (COALESCE(cardinality($8::text[]), 0) = 0 OR m.source_kind = ANY($8::text[]))
   AND (COALESCE(cardinality($9::text[]), 0) = 0 OR m.lifecycle_state = ANY($9::text[]))
   AND (COALESCE(cardinality($10::text[]), 0) = 0 OR c.connection_state = ANY($10::text[]))
   AND ($11::uuid IS NULL OR m.machine_pool_id = $11::uuid)
), visible_page AS (
 SELECT id, sort_key, sort_is_null FROM listed WHERE $12::boolean = false
  OR ($1::boolean = false AND (sort_key, id) > ($13::text, $14::uuid))
  OR ($1::boolean = true AND (sort_key, id) < ($13::text, $14::uuid))
 ORDER BY CASE WHEN NOT $1::boolean THEN sort_key END ASC, CASE WHEN $1::boolean THEN sort_key END DESC,
  CASE WHEN NOT $1::boolean THEN id END ASC, CASE WHEN $1::boolean THEN id END DESC
 LIMIT $15::bigint
),
sources AS (
  SELECT m.id, m.org_id, m.source_kind, m.display_name, m.description, m.provider, m.lifecycle_state,
         connection.connection_state,
         m.last_observed_at, m.deleted_at, m.created_at, m.updated_at, page.sort_key, page.sort_is_null,
         'org_role'::text AS access_source_kind, NULL::uuid AS access_project_id, NULL::uuid AS access_grant_id, ''::text AS access_grant_source_kind, true AS can_manage
  FROM visible_page page
  JOIN machines m ON m.id = page.id
  JOIN machine_connection_states connection ON connection.org_id = m.org_id AND connection.machine_id = m.id
  WHERE EXISTS (
    SELECT 1
    FROM is_admin
    WHERE value
  )
  UNION ALL
  SELECT m.id, m.org_id, m.source_kind, m.display_name, m.description, m.provider, m.lifecycle_state,
         connection.connection_state,
         m.last_observed_at, m.deleted_at, m.created_at, m.updated_at, page.sort_key, page.sort_is_null,
         'project_machine_grant'::text AS access_source_kind, pmg.project_id AS access_project_id, pmg.id AS access_grant_id, pmg.source_kind AS access_grant_source_kind, false AS can_manage
  FROM visible_page page
  JOIN project_machine_grants pmg
    ON pmg.org_id = $2
   AND pmg.machine_id = page.id
  JOIN machines m ON m.org_id = pmg.org_id AND m.id = pmg.machine_id AND m.deleted_at IS NULL AND m.lifecycle_state = 'active'
  JOIN machine_connection_states connection ON connection.org_id = m.org_id AND connection.machine_id = m.id
  WHERE (SELECT value FROM is_admin)
    OR EXISTS (
      SELECT 1
      FROM visible_projects vp
      WHERE vp.project_id = pmg.project_id
    )
)
SELECT sources.id, sources.org_id, sources.source_kind, sources.display_name, sources.description, sources.provider, sources.lifecycle_state, sources.connection_state, sources.last_observed_at, sources.deleted_at, sources.created_at, sources.updated_at, sources.access_source_kind, sources.access_project_id, sources.access_grant_id, sources.access_grant_source_kind, sources.can_manage, sources.sort_key, sources.sort_is_null
FROM sources
ORDER BY CASE WHEN NOT $1::boolean THEN sources.sort_key END ASC, CASE WHEN $1::boolean THEN sources.sort_key END DESC,
 CASE WHEN NOT $1::boolean THEN sources.id END ASC, CASE WHEN $1::boolean THEN sources.id END DESC,
 sources.access_source_kind, sources.access_project_id, sources.access_grant_id
`

