const updateMachineObservation = `-- name: UpdateMachineObservation :exec
UPDATE machines
SET last_observed_at = statement_timestamp(),
    metadata = CASE
      WHEN $1::jsonb = '{}'::jsonb THEN metadata
      ELSE jsonb_set(metadata, '{observed_platform}', $1::jsonb, true)
    END,
    updated_at = statement_timestamp()
WHERE org_id = $2
  AND id = $3
  AND lifecycle_state = 'active'
`

type UpdateMachineObservationParams struct {
	ObservedPlatform json.RawMessage
	OrgID            uuid.UUID
	ID               uuid.UUID
}

// @sqlc-vet-disable machines-deleted-at
// lifecycle_state = 'active' excludes soft-deleted machines.
func (q *Queries) UpdateMachineObservation(ctx context.Context, arg UpdateMachineObservationParams) error {
	_, err := q.db.Exec(ctx, updateMachineObservation, arg.ObservedPlatform, arg.OrgID, arg.ID)
	return err
}

const upsertProjectMachineGrant = `-- name: UpsertProjectMachineGrant :one
INSERT INTO project_machine_grants(org_id, project_id, machine_id, source_kind, project_machine_pool_grant_id, description, idempotency_key, metadata, created_at, updated_at)
SELECT project.org_id, project.id, machine.id, $1, $2::uuid, $3, $4, $5, statement_timestamp(), statement_timestamp()
FROM projects project
JOIN machines machine ON machine.org_id = project.org_id
  AND machine.id = $6
  AND machine.deleted_at IS NULL
WHERE project.org_id = $7 AND project.id = $8
  AND (
    (
      $1::text = 'explicit'
      AND machine.source_kind = 'byo'
      AND machine.lifecycle_state = 'active'
    )
    OR EXISTS (
      SELECT 1
      FROM project_machine_pool_grants pool_grant
      WHERE pool_grant.project_id = project.id
        AND pool_grant.id = $2::uuid
        AND pool_grant.machine_pool_id = machine.machine_pool_id
        AND $1::text = 'pool'
        AND machine.source_kind = 'pool'
        AND machine.lifecycle_state IN ('provisioning', 'provision_failed', 'active')
    )
  )
ON CONFLICT (project_id, machine_id) DO NOTHING
RETURNING id, org_id, project_id, machine_id, source_kind, project_machine_pool_grant_id, description, coalesce(idempotency_key, '') AS idempotency_key, metadata, created_at, updated_at
`

type UpsertProjectMachineGrantParams struct {
	SourceKind                string
	ProjectMachinePoolGrantID *uuid.UUID
	Description               string
	IdempotencyKey            *string
	Metadata                  json.RawMessage
	MachineID                 uuid.UUID
	OrgID                     uuid.UUID
	ProjectID                 uuid.UUID
}

type UpsertProjectMachineGrantRow struct {
	ID                        uuid.UUID
	OrgID                     uuid.UUID
	ProjectID                 uuid.UUID
	MachineID                 uuid.UUID
	SourceKind                string
	ProjectMachinePoolGrantID *uuid.UUID
	Description               string
	IdempotencyKey            string
	Metadata                  json.RawMessage
	CreatedAt                 time.Time
	UpdatedAt                 time.Time
}

func (q *Queries) UpsertProjectMachineGrant(ctx context.Context, arg UpsertProjectMachineGrantParams) (UpsertProjectMachineGrantRow, error) {
	row := q.db.QueryRow(ctx, upsertProjectMachineGrant,
		arg.SourceKind,
		arg.ProjectMachinePoolGrantID,
		arg.Description,
		arg.IdempotencyKey,
		arg.Metadata,
		arg.MachineID,
		arg.OrgID,
		arg.ProjectID,
	)
	var i UpsertProjectMachineGrantRow
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.ProjectID,
		&i.MachineID,
		&i.SourceKind,
		&i.ProjectMachinePoolGrantID,
		&i.Description,
		&i.IdempotencyKey,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const validateMachineDaemonBootstrap = `-- name: ValidateMachineDaemonBootstrap :one
SELECT installation.id AS installation_id,
       machine.id AS machine_id,
       machine.org_id AS org_id,
       token.id AS daemon_token_id
FROM machine_daemon_tokens token
JOIN machines machine ON machine.org_id = token.org_id AND machine.id = token.machine_id
CROSS JOIN installation
WHERE token.org_id = $1
  AND token.machine_id = $2
  AND token.id = $3
  AND token.revoked_at IS NULL
  AND machine.deleted_at IS NULL
  AND (
    machine.lifecycle_state = 'active'
    OR (
      token.created_by_user_id IS NULL
      AND machine.source_kind = 'pool'
      AND machine.lifecycle_state IN ('provisioning', 'provision_failed')
    )
  )
`

type ValidateMachineDaemonBootstrapParams struct {
	OrgID         uuid.UUID
	MachineID     uuid.UUID
	DaemonTokenID uuid.UUID
}

type ValidateMachineDaemonBootstrapRow struct {
	InstallationID uuid.UUID
	MachineID      uuid.UUID
	OrgID          uuid.UUID
	DaemonTokenID  uuid.UUID
}

func (q *Queries) ValidateMachineDaemonBootstrap(ctx context.Context, arg ValidateMachineDaemonBootstrapParams) (ValidateMachineDaemonBootstrapRow, error) {
	row := q.db.QueryRow(ctx, validateMachineDaemonBootstrap, arg.OrgID, arg.MachineID, arg.DaemonTokenID)
	var i ValidateMachineDaemonBootstrapRow
	err := row.Scan(
		&i.InstallationID,
		&i.MachineID,
		&i.OrgID,
		&i.DaemonTokenID,
	)
	return i, err
}
